const input = $workflow.input || {};
const workflowName = String(input.workflowName || 'IntakeClaimByCaseType').trim();
const caseType = String(input.caseType || 'MedicaidPCS').trim();
const allowedCaseTypes = ['MedicaidPCS', 'StateMedicaidHospice'];
const isHospice = caseType === 'StateMedicaidHospice';
const caseId = String(input.caseId || (isHospice ? 'PI-HSP-2026-0042' : 'PI-PCS-2026-0041'));
const providerId = String(input.providerId || (isHospice ? 'PRV-HSP-2042' : 'PRV-100482'));
const claimThreshold = 2500;
const claimTotalBilled = Number(input.claimTotalBilled || (isHospice ? 3250 : 1267.2));
const hospitalRecordAvailable = input.hospitalRecordAvailable === true || input.hospitalRecordAvailable === 'true';
const investigatorProceed = input.investigatorProceed === true || input.investigatorProceed === 'true';
const supervisorApproved = input.supervisorApproved === true || input.supervisorApproved === 'true';
const supportedWorkflows = ['IntakeClaimByCaseType', 'GetClaimDetailsByCaseType', 'ExtractServiceEvidence', 'ValidateEvidenceByCaseType', 'RequestHospitalRecord', 'IntakeHospitalRecord', 'ExtractInstitutionalEncounter', 'PrepareSupervisorPacket', 'CloseCaseAndEmitMetrics', 'SendClosureSummaryEmail'];
const base = { workflowName, caseType, caseId, gated: false, recordsAffected: 0, mockMode: true, note: 'Demo contract only; no external write is performed.' };
function result(status, recordsAffected, message, payload, gated = false) {
  return { ...base, status, recordsAffected, message, payload, gated };
}
if (!allowedCaseTypes.includes(caseType)) {
  return result('InvalidRequest', 0, `Unsupported CaseType '${caseType}'.`, { allowedCaseTypes }, true);
}
const catalog = {
  IntakeClaimByCaseType: () => result('Open', 1, 'CaseType profile selected for Medicaid claim intake.', { caseType, claimThreshold, providerRequestHours: isHospice ? 72 : 0, nextStageId: 'Stage_Evcol2' }),
  GetClaimDetailsByCaseType: () => result('Completed', isHospice ? 1 : 9, 'Claim detail contract resolved through the CaseType-specific Beeceptor route.', { sourceEndpoint: `https://medicaid-claim-demo.free.beeceptor.com/${caseType}`, claimCount: isHospice ? 1 : 9, lineCount: isHospice ? 3 : 9, totalUnits: isHospice ? 52 : 176, totalBilled: claimTotalBilled, thresholdExceeded: isHospice && claimTotalBilled >= claimThreshold }),
  ExtractServiceEvidence: () => result('Completed', 1, 'Service evidence extraction contract resolved through IXP.', { ixpProject: 'pi360_timesheets-46b073f4-ixp', ixpModel: 'PI360 Service Evidence Extractor', versionTag: 'live', documentType: isHospice ? 'Hospice Service Record' : 'Personal Care Timesheet', confidenceThreshold: 0.85, humanReviewRequired: false }),
  ValidateEvidenceByCaseType: () => result('Completed', 1, 'Deterministic threshold and evidence indicators were reconciled.', { claimThreshold, claimTotalBilled, thresholdExceeded: isHospice && claimTotalBilled >= claimThreshold, expectedHospiceOverlapMinutes: isHospice ? 360 : 0, reviewIndicatorOnly: true, nextStageId: isHospice && !hospitalRecordAvailable ? 'Stage_Prreq6' : 'Stage_Corr4a' }),
  RequestHospitalRecord: () => isHospice && investigatorProceed ? result('AwaitingProvider', 1, 'Hospital record request contract opened a 72-hour response window.', { requestId: 'REQ-HSP-0042', providerId, responseTimer: 'P3D', requestedDocument: 'Jordan Ellis hospital record', nextStageId: 'Stage_Prreq6' }) : result('Blocked', 0, 'Hospice provider request requires investigator proceed confirmation.', { requiredGate: 'investigatorProceed' }, true),
  IntakeHospitalRecord: () => result('Completed', 1, 'Hospital record intake contract accepted the supplied synthetic record.', { bucket: 'Hospital Records', documentName: 'jordan_ellis_synthetic_medical_record_packet.pdf', patientClass: 'Observation', arrivalAt: '2026-07-14T08:20:00-05:00', dischargeAt: '2026-07-16T10:00:00-05:00' }),
  ExtractInstitutionalEncounter: () => result('NeedsHumanReview', 1, 'Institutional encounter extraction contract resolved through IXP with omitted fields routed to review.', { ixpProject: 'pi360-institutional-encounter-extractor-53d63c92-ixp', ixpModel: 'PI360 Institutional Encounter Extractor', versionTag: 'live', patientClass: 'Observation', arrivalAt: '2026-07-14T08:20:00-05:00', encounterId: null, dischargeAt: null, humanReviewFields: ['Encounter ID', 'Discharge Date and Time'], locationConflictMinutes: 360, reviewIndicatorOnly: true }),
  PrepareSupervisorPacket: () => result('Completed', 1, 'Supervisor packet contract assembled investigator findings and agentic evidence.', { packetId: `PKT-${caseId}`, tabs: ['Investigator findings', 'Agentic evidence'], patientClass: isHospice ? 'Observation' : null, adverseActionAllowed: false }),
  CloseCaseAndEmitMetrics: () => supervisorApproved ? result('Closed', 1, 'Human-approved disposition was persisted and closure metrics were emitted.', { finalStatus: 'Closed', supervisorApproved: true, insightsMetrics: ['cycle_time', 'human_gate_count', 'review_indicator_count'] }) : result('Blocked', 0, 'Supervisor approval is required before final closure.', { requiredGate: 'supervisorApproved' }, true),
  SendClosureSummaryEmail: () => supervisorApproved ? result('Queued', 1, 'Closure email contract queued the reviewed facts, disposition, and next steps.', { subject: `Program Integrity case ${caseId} closure summary`, includes: ['CaseType and claim totals', 'Investigator findings', 'Agentic evidence', 'Supervisor disposition', 'Next steps'], patientClass: isHospice ? 'Observation' : null }) : result('Blocked', 0, 'Supervisor approval is required before the closure email is queued.', { requiredGate: 'supervisorApproved' }, true)
};
const handler = catalog[workflowName];
if (!handler) {
  return result('InvalidRequest', 0, `Unknown workflowName '${workflowName}'.`, { supportedWorkflows }, true);
}
return handler();
